'use strict';
const KEY='culture-show-v1';let state;try{state=JSON.parse(localStorage.getItem(KEY))||Show.seed()}catch{state=Show.seed()}
let page='演出控制';const app=document.getElementById('app');const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.hidden=true,3500)}
function persist(){localStorage.setItem(KEY,JSON.stringify(state))}
function download(){const u=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='show-demo-report.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function btn(t,a,disabled=false,cls=''){return `<button data-action="${a}" class="${cls}" ${disabled?'disabled':''}>${t}</button>`}
function render(){document.getElementById('nav').innerHTML=['演出控制','节目编排','素材与预演','设备与故障','执行报告','组件接入'].map(x=>`<button data-page="${x}" class="${page===x?'active':''}">${x}</button>`).join('');
app.innerHTML=`<div class="top"><div><div class="eyebrow">演出自动化 / ${esc(page)}</div><h1>${esc(state.title)}</h1><div class="muted">节目版本 v${state.version} · ${esc(state.status)} · 手动触发 cue</div></div><div class="row">${btn('导出执行报告','export',false,'secondary')}${btn('重置演示','reset',false,'secondary')}</div></div><div class="notice">全链路模拟：灯光为参数示意，视频为占位描述，调音与机位为模拟指令。未调用 AI 模型、生成真实视频或连接设备；确认回执和状态变化不代表真实演出性能。</div><div class="stats"><div class="stat"><span>节目 cue</span><strong>${state.cues.length}</strong></div><div class="stat"><span>本场已执行</span><strong>${state.run?.executed||0}</strong></div><div class="stat"><span>模拟在线设备</span><strong>${Object.values(state.devices).filter(Boolean).length} / 4</strong></div><div class="stat"><span>本场故障次数</span><strong>${state.run?.failures||0}</strong></div></div><div id="content"></div>`;
const c=document.getElementById('content');const running=['运行中','故障暂停','人工接管'].includes(state.status);
if(page==='组件接入'){c.innerHTML=`<div class="card"><h2>专业组件接入计划</h2><p class="muted">当前使用本地模拟器，以下组件均尚未安装和接入。</p>${[['BlenderDMX','https://github.com/open-stage/blender-dmx','灯光预演：替换参数示意，导入场地与灯具。'],['QLC+','https://github.com/mcallegari/qlcplus','灯光控制：通过兼容协议执行确认后的灯光场景。'],['ComfyUI','https://github.com/Comfy-Org/ComfyUI','生成任务与素材文件接口。'],['Wan2.2','https://github.com/Wan-Video/Wan2.2','视频模型：按显卡与质量要求选型。'],['Companion','https://github.com/bitfocus/companion','设备联动与一键 cue 控制接口。'],['OBS WebSocket','https://github.com/obsproject/obs-websocket','导播场景切换；镜头选择策略独立实现。'],['Mix Mind','https://github.com/mlmil/Mix_Mind_v5.0','适配指定 X-Air 设备的调音控制辅助，不能直接等同于自动混音。']].map(([n,u,t])=>`<div class="item"><a href="${u}" target="_blank" rel="noopener">${n}</a><p class="muted">${t}</p></div>`).join('')}<p class="muted">真实演出需独立本地控制服务、时间同步、指令确认、超时与幂等处理、离线运行及经过验证的人工接管。浏览器原型不承担现场控制。</p></div>`;return;}
if(page==='节目编排'){c.innerHTML=`<div class="grid"><div class="card"><h2>节目 cue 清单</h2>${cueList()}</div><div class="card"><h2>添加 cue</h2><p class="muted">修改将使排练结果失效，需重新排练和发布。</p><form id="cue-form">${[['name','cue 名称','例如：副歌开始'],['lighting','灯光指令','例如：暖白面光 60%'],['video','视频描述','例如：海浪背景'],['audio','调音快照','例如：主唱快照'],['camera','机位／导摄','例如：主唱近景']].map(([n,t,p])=>`<label><span>${t}</span><input name="${n}" maxlength="180" placeholder="${p}" ${n==='name'?'required':''} ${running?'disabled':''}></label>`).join('')}<button ${running?'disabled':''}>添加到节目</button></form></div></div>`;return;}
if(page==='素材与预演'){c.innerHTML=`<div class="two"><div class="card"><h2>灯光参数示意</h2><p class="muted">按现有 cue 展示参数，用于验证工作流程；不包含灯具几何、照度或光学仿真。</p>${btn('生成模拟灯光方案','lighting',running)}${state.cues.map(q=>`<div class="step"><b>${esc(q.name)}</b><p>${esc(q.lighting)}</p></div>`).join('')}</div><div class="card"><h2>视频生成任务</h2><p class="muted">生成占位任务回执，不产生视频文件。后续由 ComfyUI 适配器替换。</p>${btn('创建模拟视频任务','video',running)}${state.artifacts.map(a=>`<div class="item"><b>${esc(a.type)} · v${a.version}</b><p class="muted">${esc(a.text)}</p></div>`).join('')}</div></div>`;return;}
if(page==='设备与故障'){c.innerHTML=`<div class="grid"><div class="card"><h2>模拟设备状态</h2>${devices()}</div><div class="card"><h2>故障演练</h2><ol class="muted"><li>通过排练并发布节目，开始模拟演出。</li><li>将任意设备设为离线，系统进入故障暂停。</li><li>恢复设备，点击恢复执行；或人工接管。</li><li>继续触发未执行 cue，查看故障记录。</li></ol>${controls()}</div></div>`;return;}
if(page==='执行报告'){c.innerHTML=`<div class="card"><h2>本场执行报告</h2>${state.run?`<pre>场次：${esc(state.run.id)}\n节目版本：v${state.run.version}\n状态：${esc(state.status)}\n执行 cue：${state.run.executed} / ${state.cues.length}\n模拟故障：${state.run.failures}\n开始：${esc(state.run.started)}\n结束：${esc(state.run.finished||'尚未结束')}\n真实延迟、同步误差与音视频质量：未测量</pre>`:'<div class="empty">尚未开始演出</div>'}<h2>操作时间线</h2>${logs()}</div>`;return;}
c.innerHTML=`<div class="grid"><section><div class="card"><div class="row between"><h2>节目与 cue</h2><span class="badge">v${state.version}</span></div>${cueList()}</div><div class="card"><h2>模拟设备</h2>${devices()}</div></section><section><div class="card"><h2>执行控制</h2><div class="step">编排 → 排练通过 → 版本发布 → 开演 → 逐条 cue → 执行报告</div>${controls()}<h3>下一条 cue</h3><pre>${esc(state.cues[state.cursor]?.name||'本场 cue 已执行完毕')}</pre></div><div class="card"><h2>最近事件</h2>${logs(6)}</div></section></div>`;}
function cueList(){return state.cues.map((q,i)=>`<div class="item"><div class="row between"><b>${i+1}. ${esc(q.name)}</b><span class="badge">${esc(q.status)}</span></div><p class="muted">灯光：${esc(q.lighting)}<br>视频：${esc(q.video)}<br>调音：${esc(q.audio)}<br>机位：${esc(q.camera)}</p></div>`).join('')}
function devices(){return Object.entries(state.devices).map(([k,v])=>`<div class="device row between"><div><b>${{lighting:'灯光控制',video:'视频播放',audio:'调音台',camera:'导播机位'}[k]}</b> <span class="badge ${v?'':'bad'}">模拟${v?'在线':'离线'}</span></div><button class="secondary" data-device="${k}">${v?'注入离线故障':'恢复在线'}</button></div>`).join('')}
function logs(n=1000){return state.logs.slice(0,n).map(l=>`<div class="item">${esc(l.message)}<div class="muted">${new Date(l.at).toLocaleString('zh-CN')}</div></div>`).join('')||'<div class="empty">暂无执行事件</div>'}
function controls(){return `<div class="row">${btn('模拟排练','rehearse',!['编排中','排练通过','已发布','已完成','已终止'].includes(state.status),'secondary')}${btn('发布当前版本','publish',state.status!=='排练通过')}${btn('开始模拟演出','start',state.status!=='已发布')}${btn('执行下一条 cue','next',state.status!=='运行中')}${btn('恢复执行','recover',state.status!=='故障暂停','secondary')}${btn('人工接管','takeover',!['运行中','故障暂停'].includes(state.status),'secondary')}${btn('确认返回自动','resume',state.status!=='人工接管','secondary')}${btn('终止本场','stop',!['运行中','故障暂停','人工接管'].includes(state.status),'danger')}</div>`}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;try{if(b.dataset.page){page=b.dataset.page;render();return}if(b.dataset.device){Show.act(state,'device',b.dataset.device)}else{const a=b.dataset.action;if(!a)return;if(a==='export'){download();return}if(a==='reset'){if(!confirm('清除当前浏览器的演出端数据并恢复样例？'))return;state=Show.seed()}else if(a==='lighting'||a==='video')Show.act(state,'generate',a==='lighting'?'灯光方案':'视频素材');else Show.act(state,a)}persist();render();toast('模拟操作已保存')}catch(err){toast(err.message)}});
document.addEventListener('submit',e=>{if(e.target.id!=='cue-form')return;e.preventDefault();try{Show.edit(state,Object.fromEntries(new FormData(e.target)));persist();render();toast('cue 已添加，请重新排练与发布')}catch(err){toast(err.message)}});
render();
